import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define IC 3
#define OC 96
#define KH 11
#define KW 11
#define STRIDE 4
#define PAD 2
#define BLOCK_M 32
#define BLOCK_N 32
#define BLOCK_K 32

__global__ void conv2d_cute_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int H, int W, int OH, int OW)
{
    const int K_total = IC * KH * KW;
    const int N_total = N * OH * OW;

    Tensor gInput = make_tensor(make_gmem_ptr(input),
        make_shape(N, IC, H, W),
        make_stride(IC * H * W, H * W, W, 1));
    Tensor gWeight = make_tensor(make_gmem_ptr(weight),
        make_shape(OC, IC, KH, KW),
        make_stride(IC * KH * KW, KH * KW, KW, 1));
    Tensor gOutput = make_tensor(make_gmem_ptr(output),
        make_shape(N, OC, OH, OW),
        make_stride(OC * OH * OW, OH * OW, OW, 1));

    __shared__ float As[BLOCK_M][BLOCK_K];
    __shared__ float Bs[BLOCK_K][BLOCK_N];

    int tx = threadIdx.x; // index within N-tile
    int ty = threadIdx.y; // index within M-tile

    int m_base = blockIdx.y * BLOCK_M;
    int n_base = blockIdx.x * BLOCK_N;

    int m = m_base + ty;
    int n = n_base + tx;

    bool n_valid = n < N_total;
    int b = 0, oh = 0, ow = 0;
    if (n_valid) {
        int spatial = OH * OW;
        b = n / spatial;
        int rem = n % spatial;
        oh = rem / OW;
        ow = rem % OW;
    }

    float acc = 0.f;
    const int KHW = KH * KW;
    int num_k_tiles = (K_total + BLOCK_K - 1) / BLOCK_K;

    for (int kt = 0; kt < num_k_tiles; ++kt) {
        int k_a = kt * BLOCK_K + tx;
        if (m < OC && k_a < K_total) {
            int c   = k_a / KHW;
            int rem = k_a % KHW;
            int khi = rem / KW;
            int kwi = rem % KW;
            As[ty][tx] = gWeight(m, c, khi, kwi);
        } else {
            As[ty][tx] = 0.f;
        }

        int k_b = kt * BLOCK_K + ty;
        float bval = 0.f;
        if (n_valid && k_b < K_total) {
            int c   = k_b / KHW;
            int rem = k_b % KHW;
            int khi = rem / KW;
            int kwi = rem % KW;
            int row = oh * STRIDE - PAD + khi;
            int col = ow * STRIDE - PAD + kwi;
            if (row >= 0 && row < H && col >= 0 && col < W) {
                bval = gInput(b, c, row, col);
            }
        }
        Bs[ty][tx] = bval;

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BLOCK_K; ++kk) {
            acc += As[ty][kk] * Bs[kk][tx];
        }
        __syncthreads();
    }

    if (m < OC && n_valid) {
        float val = acc + (bias ? bias[m] : 0.f);
        gOutput(b, m, oh, ow) = val;
    }
}

torch::Tensor conv2d_cute(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "input and weight must be CUDA tensors");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "Expect float32 input");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK((int)weight.size(0) == OC && (int)weight.size(1) == IC &&
                (int)weight.size(2) == KH && (int)weight.size(3) == KW,
                "weight shape mismatch with fixed conv config");

    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();
    torch::Tensor bias_c;
    const float* bias_ptr = nullptr;
    if (bias.defined()) {
        bias_c = bias.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }

    int N = (int)input_c.size(0);
    int H = (int)input_c.size(2);
    int W = (int)input_c.size(3);
    int OH = (H + 2 * PAD - KH) / STRIDE + 1;
    int OW = (W + 2 * PAD - KW) / STRIDE + 1;

    auto output = torch::empty({N, OC, OH, OW}, input_c.options());

    dim3 block(BLOCK_N, BLOCK_M);
    int N_total = N * OH * OW;
    dim3 grid((N_total + BLOCK_N - 1) / BLOCK_N, (OC + BLOCK_M - 1) / BLOCK_M);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv2d_cute_kernel<<<grid, block, 0, stream>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, H, W, OH, OW);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "conv2d_cute launch failed");
    return output;
}
"""

cute_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self._ext = cute_ext

    def forward(self, x):
        x = x.cuda()
        return self._ext.conv2d_cute(x, self.conv1.weight, self.conv1.bias)

